ruleToc.chapterName:
@js:
var a = result;
var h2 = a.closest('h2');
var name = '';
if (h2) {
  var c = h2.cloneNode(true);
  c.querySelectorAll('.caption, .pagenum').forEach(function (el) { el.remove(); });
  name = c.textContent.replace(/\s+/g, ' ').trim().replace(/_/g, ' ');
}
result = name || a.id || '';

ruleContent.content:
@js:
var anchor = vars.chapterUrl.split('#')[1] || '';
var a = doc.querySelector('h2 > a[id="' + anchor + '"]');
if (!a) { result = ''; }
else {
  var h2 = a.closest('h2');
  var html = '';
  var n = h2.nextElementSibling;
  while (n && n.tagName !== 'H2') { html += n.outerHTML; n = n.nextElementSibling; }
  result = html.replace(/<span class="pagenum">[\s\S]*?<\/span>/g, '');
}
